service.method:

UPDATE SCODE
	SET
		  TEXT1		      = ${GRADENAME}
		, CHANGE_DATE     = ${current.DATE}
		, CHANGE_TIME     = ${current.TIME}
		, CHANGE_USER_ID  = ${session.ID}	
		, SORT_SEQ		  = ${SORT_SEQ}
		, DEL_FLAG		  = ${DEL_FLAG}		  
WHERE
		HOUSE_CODE        = ${session.HOUSE_CODE}
	AND TYPE 		      = 'UX049'
	AND CODE              = ${GRADECODE}
	AND LANGUAGE 		  = ${LANGUAGE}


INSERT INTO SCODE
	(
		  HOUSE_CODE
		, TYPE 
		, CODE
		, LANGUAGE
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, SORT_SEQ
		, USE_FLAG
		, TEXT1
		, DEL_FLAG
	)
	VALUES
	(
		  ${session.HOUSE_CODE}
		, 'UX049'
		, ${GRADECODE}
		, ${LANGUAGE}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}				
		, ${SORT_SEQ}
		, 'Y'
		, ${GRADENAME}
		, 'N'
	)


UPDATE SCODE
	SET
		  DEL_FLAG	      = 'Y'
		, CHANGE_DATE     = ${current.DATE}
		, CHANGE_TIME     = ${current.TIME}
		, CHANGE_USER_ID  = ${session.ID}			  
WHERE
		HOUSE_CODE        = ${session.HOUSE_CODE}
	AND TYPE 		      = 'UX049'
